SettingsService.set("auto_allocate_wounds", true)
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 2:
		for m in u.models:
			m["wounds"] = 99
			m["current_wounds"] = 99
return true

var sc = tree.current_scene.get_node_or_null("ShootingController")
if sc and sc.resolution_dock and sc.resolution_dock.is_active():
	sc.resolution_dock.primary_button.emit_signal("pressed")
return true

var d = tree.root.get_node_or_null("StratagemDialog")
if d and d.visible and int(PhaseManager.get_current_phase_instance().get_pending_stratagem_window_decider()) == 2:
	d.get_node("Content/DeclineButton").emit_signal("pressed")
return true

